"""Phase 5C: programmatic tables -> docs/phase5_report_tables.md (every number read from results/phase5/5a_array.json / .npz)."""
from _common import RES, ROOT, np, THETA0, CASES, LABEL
import json

j = json.load(open(RES / "5a_array.json")); z = np.load(RES / "5a_array.npz")
S = j["setup"]; J = j["30"]; K = j["40"]; f = z["f"]
L = ["# Phase 5 tables (generated by `experiments/phase5/5c_tables.py`; do not edit by hand)", "",
     "All numbers: four-element isotropic array, actual Phase 4 res-30 transfer functions unless stated, inside mask_common (0.231-0.268; domain-limited, post hoc upper edge). "
     "Power = |AF|^2/16. Angles in degrees. \"Trimmed\" always means phase-intercept-trimmed PhC (one constant phase per channel at f0), never ideal TTD.", ""]


def tab(head, rows):
    e = lambda c: str(c).replace("|", "\\|")
    return ["| " + " | ".join(e(c) for c in head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(e(c) for c in r) + " |" for r in rows] + [""]


LB = lambda k: LABEL[k]
L += ["## Table A. Array definition", ""]
L += tab(["quantity", "value"], [["steering angle theta0", f"{S['theta0_deg']:.1f} deg"], ["center frequency f0", f"{S['f0']}"], ["lambda0 = 1/f0", f"{S['lambda0']:.4f} a"],
        ["target delay step dtau_target", f"{S['dtau_target']} a/c (f0 x dtau = {S['delay_quantum_cycles']:.3f} carrier cycle)"],
        ["pitch d = dtau_target / sin(theta0)", f"{S['d']:.4f} a"], ["d / lambda0 at f0", f"{S['d_over_lambda0']:.4f}"], ["d / lambda over the band", f"{S['d_over_lambda_band'][0]:.3f} - {S['d_over_lambda_band'][1]:.3f}"],
        ["common band", f"{S['f_low']} - {S['f_high']} ({S['n_freq']} samples, step 5e-4)"], ["design-lobe window |sin(theta) - sin(theta0)| <=", f"{S['window_halfwidth_sin']:.5f} = 1/(2 f_max d) (theta {S['window_theta_deg'][0]:.2f} to {S['window_theta_deg'][1]:.2f} deg)"],
        ["HPBW of ideal TTD at f0", f"{S['hpbw_ideal_f0_deg']:.3f} deg"], ["tolerance tol_pt = 0.05 HPBW", f"{S['tol_pt_deg']:.3f} deg"],
        ["largest fraction of the window used by a tracked lobe (fixed / ideal / raw / trimmed)", " / ".join(f"{j['window_use_max_frac'][k]:.3f}" for k in CASES)]])
L += ["## Table B. Pointing performance (theta_peak - theta0, deg)", ""]
rows = [[LB(k), f"{J['max_abs_err'][k]:.4f}", f"{J['rms_err'][k]:.4f}", *[f"{v:+.4f}" for v in J["err_low_f0_high"][k]]] for k in CASES]
L += tab(["case", "max abs", "RMS", "low edge (0.231)", "f0 (0.2495)", "high edge (0.268)"], rows)
L += ["Analytic fixed-phase check: sin(theta) = (f0/f) sin(theta0); max deviation of the array-factor peak over the band = " + f"{j['fixed_analytic_check_max_dev_deg']:.2e} deg.", ""]
L += ["## Table C. Squint reduction", ""]
rows = [[LB(k), f"{J['R_squint'][k]:.4f}", f"{J['R_squint_spread'][k]:.4f}", f"{J['vs_ideal_max'][k]:.4f}", f"{J['vs_ideal_rms'][k]:.4f}"] for k in CASES]
L += tab(["case", "R_squint = max|err| / max|err_fixed|", "offset-removed spread ratio (diagnostic)", "max |theta - theta_ideal| (deg)", "RMS |theta - theta_ideal| (deg)"], rows)
L += ["R_squint <= 0.20 is a stretch engineering target, not a criterion. R_squint for raw PhC includes its absolute offset; the offset-removed ratio isolates frequency dependence.", ""]
L += ["## Table D. Peak power, HPBW, strongest other lobe at low / f0 / high", ""]
rows = []
for k in CASES:
    for q, nm, fmt in (("gain_low_f0_high", "peak power", "{:.5f}"), ("hpbw_low_f0_high", "HPBW (deg)", "{:.3f}"), ("strongest_db_low_f0_high", "strongest other lobe (dB re design peak)", "{:+.3f}"), ("strongest_theta_low_f0_high", "its angle (deg)", "{:.2f}"), ("n3db_low_f0_high", "interior lobes within 3 dB", "{}")):
        rows.append([LB(k), nm, *[fmt.format(v) for v in J[q][k]]])
L += tab(["case", "quantity", "0.231", "0.2495", "0.268"], rows)
L += ["Minimum design-lobe peak power over the band: " + "; ".join(f"{LB(k)} {J['gain_min'][k]:.5f} ({10*np.log10(J['gain_min'][k]):.4f} dB)" for k in CASES) + ".",
      "Power at the two endfire samples (-90 / +90 deg, dB re design peak) at low / f0 / high, ideal TTD: " + "; ".join(f"[{a:.2f}, {b:.2f}]" for a, b in J["edge_db_low_f0_high"]["ideal"]) + ". These are skirts of grating lobes just outside the visible region, not counted as lobes.",
      "Visible analytic grating-lobe angles of the ideal design lobe (deg) at low / f0 / high: " + "; ".join(str([round(x, 2) for x in a]) for a in j["grating_ideal_angles_low_f0_high"]) + ".", ""]
L += ["## Table E. Actual amplitudes vs |H_m| = 1 (same phases; diagnostic only)", ""]
rows = [[LB(k), f"{j['amp_diag'][k]['max_dtheta_deg']:.2e}", f"{j['amp_diag'][k]['max_dgain']:.5f}", f"{j['amp_diag'][k]['max_dgain_db']:.4f}", f"{j['amp_diag'][k]['max_dstrongest_db']:.1e}"] for k in ("raw", "trim")]
L += tab(["case", "max |d theta_peak| (deg)", "max |d peak power|", "max |d peak power| (dB)", "max |d strongest-lobe level| (dB)"], rows)
L += [f"Phase 4 amplitude imbalance (20 log10 max|H|/min|H|) over the band: max {j['amp_imbalance_db_max']:.4f} dB.", ""]
L += ["## Table F. Resolution sensitivity (res 30 production vs res 40 confirmation Phase 4 transfer functions)", ""]
rows = []
for k in ("raw", "trim"):
    rc = j["res_check"][k]
    rows.append([LB(k), f"{J['max_abs_err'][k]:.4f} / {K['max_abs_err'][k]:.4f}", f"{J['R_squint'][k]:.4f} / {K['R_squint'][k]:.4f}", f"{J['vs_ideal_max'][k]:.4f} / {K['vs_ideal_max'][k]:.4f}",
                 f"{J['gain_min'][k]:.5f} / {K['gain_min'][k]:.5f}", f"{rc['max_dtheta_deg']:.4f}", f"{rc['d_gain']:.4f}", f"{rc['d_strongest_db']:.1e}"])
L += tab(["case", "max |err| res30 / res40", "R_squint res30 / res40", "max |theta - ideal| res30 / res40", "min peak power res30 / res40", "max |theta30 - theta40| (deg)", "max |d peak power|", "max |d strongest lobe| (dB)"], rows)
tol3 = S["tol_pt_deg"] / 3
chk = []
for k in ("raw", "trim"):
    rc = j["res_check"][k]
    chk.append(rc["max_dtheta_deg"] <= tol3 and rc["d_max_abs_err"] <= tol3 and rc["d_R_squint"] <= 0.02 and rc["d_gain"] <= 0.02 and rc["d_vs_ideal_max"] <= tol3 and rc["d_strongest_db"] <= 0.5)
L += [f"Predeclared agreement criteria (Revision 6, item 9): theta, max-error and trimmed-vs-ideal changes <= tol_pt/3 = {tol3:.3f} deg; R_squint change <= 0.02; peak power change <= 0.02; strongest-lobe change <= 0.5 dB. "
      f"Result: raw {'met' if chk[0] else 'NOT met'}; trimmed {'met' if chk[1] else 'NOT met'}.", ""]
L += ["## Table G. Phase 4 phase error vs Phase 5 pointing (res 30; res 40 in parentheses)", ""]
rows = []
for k in ("raw", "trim"):
    a, b = J[f"phase_link_{k}"], K[f"phase_link_{k}"]
    rows.append([LB(k), f"{a['max_abs_eps_rad']:.4f} ({b['max_abs_eps_rad']:.4f})", f"{a['g_slope_rad_per_element_f0']:+.4f}", f"{a['pred_shift_max_deg']:.4f}", f"{a['numeric_shift_vs_ideal_max_deg']:.4f} ({b['numeric_shift_vs_ideal_max_deg']:.4f})", f"{a['pred_minus_numeric_max_deg']:.4f}"])
L += tab(["case", "max_m,f |phase error vs ideal| (rad)", "phase slope across elements at f0 (rad/element)", "linear-model max shift (deg)", "numerical max |theta - theta_ideal| (deg)", "max |model - numerical| (deg)"], rows)
L += [f"Trimmed PhC: max phase error {J['phase_link_trim']['max_abs_eps_rad']:.4f} rad -> max pointing difference from ideal TTD {J['vs_ideal_max']['trim']:.4f} deg = {J['vs_ideal_max']['trim']/S['hpbw_ideal_f0_deg']*100:.2f}% of the ideal HPBW (tolerance {S['tol_pt_deg']:.3f} deg).", ""]

# physical mapping
c0 = 299792458.0; a_ = lambda lam: lam * S["f0"]
rows = []
for name, lam in (("A. microwave: carrier 30 GHz", c0 / 30e9), ("A2. mm-wave: carrier 94 GHz", c0 / 94e9), ("B. optical phased array: carrier 1550 nm", 1550e-9)):
    a = a_(lam); dt = S["dtau_target"] * a / c0; d_ = S["d"] * a
    u = (lambda x: f"{x*1e3:.3f} mm" if x > 1e-4 else (f"{x*1e6:.3f} um" if x > 1e-7 else f"{x*1e9:.1f} nm")); tm = lambda x: f"{x*1e12:.2f} ps" if x > 1e-12 else f"{x*1e15:.2f} fs"
    rows.append([name, u(lam), u(a), tm(S["dtau_target"] * a / c0), tm(dt), u(d_), f"{u(8*a)} - {u(11*a)}"])
L += ["## Table H. Illustrative normalized-to-physical mapping (carrier = the wave being beamformed; 2-D lossless model, not a manufacturable device)", "",
      "f_normalized = a/lambda0 = 0.2495 so lambda0 = 4.008 a. One-period delay = channel increment = 3.9323 a/c (Phase 4: one extra period per channel). Pitch from the Phase 5 matching d = c dtau / sin(theta0) = 7.8646 a. Device section length N = 8-11 periods (excluding the 6-period reference spans).", ""]
L += tab(["scaling", "free-space lambda0", "lattice constant a", "one-period delay", "channel increment dtau", "array pitch d", "N = 8 - 11 section length"] , rows)
a = a_(1550e-9); rf = 30e9
n_per = (0.5 * (c0 / rf / 2)) / c0 / (S["dtau_target"] * a / c0)
L += ["RF-photonic caveat (photonic carrier vs RF beamforming frequency): in a 1550 nm photonic system the lattice constant is " + f"{a*1e9:.1f} nm and one period delays the modulation envelope by {S['dtau_target']*a/c0*1e15:.2f} fs. "
      f"Steering a 30 GHz RF array with half-wave pitch (d = 5 mm, theta0 = 30 deg) needs an incremental delay d sin(theta0)/c = {0.5*5e-3/c0*1e12:.2f} ps, i.e. about {n_per:.0f} periods per element step ({n_per*a*1e6:.0f} um), if the same group delay per period held for such long sections (not demonstrated). "
      "The Phase 5 one-period matching therefore describes an optical-carrier phased array (the beamformed wave is the PhC carrier), not an RF array fed by this channel family; the RF-photonic use needs much longer or slower delay sections, and the optical-carrier phase intercept is irrelevant there, since the RF phase is set by the envelope delay.", ""]
(ROOT / "docs" / "phase5_report_tables.md").write_text("\n".join(L))
print("\n".join(L)[-3800:])
